function residuals_block_121(parameters::AbstractVector, previous_solution::AbstractVector, external_solution::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(previous_solution) == 1
    @assert length(external_solution) == 0
    @assert length(solution) == 3
    complete_parameters = complete_parameter_values(parameters)
    return [
        solution[1] - (solution[2] ^ (0.25 * complete_parameters[40] - 0.25) * previous_solution[1]) / solution[3] ^ complete_parameters[40],
        solution[2] - min(1.0e12, max(eps(), complete_parameters[64])),
        solution[3] - min(1.0e12, max(eps(), previous_solution[1])),
    ]
end

function residuals_block_122(parameters::AbstractVector, previous_solution::AbstractVector, external_solution::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(previous_solution) == 1
    @assert length(external_solution) == 0
    @assert length(solution) == 3
    complete_parameters = complete_parameter_values(parameters)
    return [
        solution[1] - solution[2] ^ (0.25 - 0.25 * complete_parameters[40]) * solution[3] ^ complete_parameters[40],
        solution[2] - min(1.0e12, max(eps(), complete_parameters[64])),
        solution[3] - min(1.0e12, max(eps(), previous_solution[1])),
    ]
end

function residuals_block_123(parameters::AbstractVector, previous_solution::AbstractVector, external_solution::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(previous_solution) == 1
    @assert length(external_solution) == 0
    @assert length(solution) == 1
    complete_parameters = complete_parameter_values(parameters)
    return [
        -(previous_solution[1]) + solution[1],
    ]
end

function residuals_block_124(parameters::AbstractVector, previous_solution::AbstractVector, external_solution::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(previous_solution) == 0
    @assert length(external_solution) == 0
    @assert length(solution) == 3
    complete_parameters = complete_parameter_values(parameters)
    return [
        -(solution[1] ^ 4) + solution[2],
        ((-(complete_parameters[65]) * (solution[3] ^ 4 - 1) + solution[3] ^ 4) - (1 - complete_parameters[65]) * ((complete_parameters[66] * (-(complete_parameters[64]) + solution[2]) + complete_parameters[64] * complete_parameters[148] ^ 4) - 1)) - 1,
        solution[3] - solution[1] / complete_parameters[24],
    ]
end

function residuals_block_125(parameters::AbstractVector, previous_solution::AbstractVector, external_solution::AbstractVector, solution::AbstractVector)
    @assert length(parameters) == length(PARAMETER_NAMES)
    @assert length(previous_solution) == 0
    @assert length(external_solution) == 0
    @assert length(solution) == 1
    complete_parameters = complete_parameter_values(parameters)
    return [
        (-(solution[1]) * complete_parameters[70] + solution[1]) - complete_parameters[55] * (1 - complete_parameters[70]),
    ]
end

function residuals_blocks(parameters::AbstractVector, previous_solutions::AbstractVector, external_solutions::AbstractVector, solutions::AbstractVector)
